                    candidate,
                    reliable,
                    preference: subtitlePreference(candidate, language),
                    score:
                        (candidate.identityMatched ? 100 : 0) +
                        (candidate.titleMatched ? 50 : 0) +
                        (candidate.seasonPackVerified ? 20 : 0) +
                        overlaps * 10 +
                        (lang ? 5 : 0) +
                        (preference < 0 ? 0 : (wanted.length - preference) / 10),
