        if (
            !title ||
            /^(?:subtitles?|字幕|中文|简中|繁中|chs|cht|zh(?:[-_. ]?(?:cn|tw))?)[ ._-]*$/i.test(title)
        )
            return { row, needsIdentity: true, releaseWarning };
